#!/bin/sh
# version: 0.2.1
# vela-agentic guard (dual-target: Claude Code + GitHub Copilot) - a pre-tool hook on the shell and file-write
# tools. Exit 2 denies on BOTH hosts; exit 0 allows. Denies:
#   apply      `vela apply`, or `--auto-approve` / `--yes` on a vela command - unless the HOST process was started
#              with VELA_APPLY_APPROVED=1 (an inline prefix typed by the agent does not count);
#   generated  writing a generated file - `Models/Generated/`, `*.g.cs`, `*.generated.cs`, or any file whose head
#              carries `<auto-generated` (the Roles class, typed messages, wherever `--out` put them) -
#              regenerate it with `vela models`;
#   git        a push to main/master (named, or the current branch), a forced push (`--force-with-lease` is
#              allowed off main/master), `--no-verify` on commit or push;
#   secrets    a secret literal in a shell command or in written content: a secret-named flag with a literal
#              value, `--secure-config Name=value` (use `Name=@file`), an Authorization header, printing a secret
#              variable or the whole environment, a known secret shape - plus what gitleaks finds, when installed.
#
# Usage: guard.sh <host>   where host = cc (Claude Code) | cp (Copilot)
# Reads the hook payload JSON on stdin. POSIX sh + awk + grep only (macOS, Linux, Git Bash on Windows): nothing to
# install on a cloud agent. gitleaks is used when present, never required.
#
# Shell commands: a segment (split on ; && || | & newline, subshells, backticks) is a vela or git command when
# its command word is `vela` / `git` (any path, optionally after env assignments / env / command / exec / sudo /
# time / nohup / dotnet [tool run]). Quoted strings and heredoc bodies are data for the apply and git rules
# (commit messages, PR bodies, grep patterns), but are scanned for secrets (a PR body must not carry one either).
# `sh -c` / `eval` payloads are checked conservatively for apply. `vela apply --help` is allowed.
# Known limit (by design, see hooks/README.md): indirection such as `v=vela; $v apply` is not caught.
host="$1"
input="$(cat)"
approved=0; [ "$VELA_APPLY_APPROVED" = "1" ] && approved=1
deny() {
  echo "Blocked by vela-agentic: $1" >&2
  exit 2
}
deny_apply() {
  deny "$1 A human must approve by starting the session with VELA_APPLY_APPROVED=1 (stop-before-apply)."
}
# jget <key> <json>: the first string value of "key" at any depth, unescaped (a key inside another string value
# is escaped in the payload, so it cannot match). `jget '' <json>` unescapes the whole text.
jget() {
  printf '%s' "$2" | awk -v key="$1" '
    { s = s $0 "\n" }
    END {
      i = 1
      if (key != "") { if (!match(s, "\"" key "\"[ \t\r\n]*:[ \t\r\n]*\"")) exit; i = RSTART + RLENGTH }
      out = ""; n = length(s)
      for (; i <= n; i++) {
        c = substr(s, i, 1)
        if (c == "\\") {
          i++; e = substr(s, i, 1)
          if (e == "n") out = out "\n"; else if (e == "t") out = out "\t"; else if (e == "r") out = out "\r"
          else if (e == "u") out = out "\\u"; else out = out e
          continue
        }
        if (c == "\"" && key != "") break
        out = out c
      }
      printf "%s", out
    }'
}

# The tool's arguments: Claude Code `tool_input`; Copilot `toolArgs` (an object, or a JSON string).
cwd="$(jget cwd "$input")"
json="$input"; ta="$(jget toolArgs "$input")"; [ -n "$ta" ] && json="$ta"
cmd="$(jget command "$json")"
path=""; for k in file_path path notebook_path filePath; do [ -n "$path" ] || path="$(jget $k "$json")"; done

# --- secrets: never print the value, only what kind of secret it is --------------------------------------------
secret_shapes() {  # $1 text, $2 where
  printf '%s\n' "$1" | grep -qE -- '-----BEGIN [A-Z ]*PRIVATE KEY-----' && deny "$2 holds a private key."
  printf '%s\n' "$1" | grep -qE '[A-Za-z0-9_~.-]{3}[0-9]Q~[A-Za-z0-9_~.-]{31,34}' && deny "$2 holds what looks like an Entra ID client secret."
  printf '%s\n' "$1" | grep -qE '(gh[pousr]_[A-Za-z0-9]{36}|github_pat_[A-Za-z0-9_]{60,}|xox[abprs]-[A-Za-z0-9-]{10,}|AKIA[0-9A-Z]{16})' \
    && deny "$2 holds what looks like an access token or key."
  printf '%s\n' "$1" | grep -qiE '(ClientSecret|Password|Pwd|AccountKey|SharedAccessKey)=[^;$<{"'"'"'[:space:]]{6,}' \
    && deny "$2 holds a connection string with a secret - read it from configuration or the environment."
  if command -v gitleaks >/dev/null 2>&1; then
    conf=""; [ -n "$cwd" ] && [ -f "$cwd/.gitleaks.toml" ] && conf="$cwd/.gitleaks.toml"
    printf '%s\n' "$1" | gitleaks stdin --no-banner -l error --redact ${conf:+--config "$conf"} >/dev/null 2>&1
    [ $? = 1 ] && deny "$2 holds a secret found by gitleaks - use a placeholder, a file, or an environment variable."
  fi
  return 0
}

# --- file writes ------------------------------------------------------------------------------------------------
if [ -z "$cmd" ]; then
  [ -n "$path" ] || exit 0
  gen=0
  case "$path" in */Models/Generated/*|Models/Generated/*|*.g.cs|*.generated.cs) gen=1 ;; esac
  f="$path"; case "$f" in /*|[A-Za-z]:*) ;; *) [ -n "$cwd" ] && f="$cwd/$f" ;; esac
  [ -f "$f" ] && head -5 "$f" 2>/dev/null | grep -q '<auto-generated' && gen=1
  [ $gen = 1 ] && deny "\"$path\" is generated - change what it is generated from and regenerate (vela models); never edit it by hand."
  secret_shapes "$(jget '' "$json")" "The content written to \"$path\""
  exit 0
fi

# --- shell commands ---------------------------------------------------------------------------------------------
printf '%s\n' "$cmd" | grep -oiE -- "--?[a-z0-9_-]*(secret|password|passwd|token|api-?key|access-?key|connection-?string)[a-z0-9_-]*(=|[[:space:]]+)[\"']?[^[:space:]\"'\$@<{(-][^[:space:]\"']{5,}" \
  | grep -qviE -- '^--?[a-z0-9_-]*-(file|path|env|name|id|type|url|endpoint)(=|[[:space:]])' \
  && deny 'a secret is passed as a literal command-line value - read it from a file or an environment variable (it would land in logs and history).'
printf '%s\n' "$cmd" | grep -qE -- "--secure-config(=|[[:space:]]+)[\"']?[A-Za-z0-9_.-]+=[^@[:space:]\"'\$<]" \
  && deny 'a --secure-config value is a literal - pass it from a file: --secure-config Name=@file.'
printf '%s\n' "$cmd" | grep -qiE "Authorization:[[:space:]]*(Bearer|Basic)[[:space:]]+[^\$[:space:]\"'<]{8,}" \
  && deny 'an Authorization header carries a literal credential - read it from an environment variable.'
printf '%s\n' "$cmd" | grep -qE '(^|[;&|(`[:space:]])(echo|printf|printenv)[^;&|]*(SECRET|PASSWORD|TOKEN|API_?KEY|CONNECTION_?STRING)' \
  && deny 'this prints a secret variable - check that it is set with [ -n "$NAME" ] instead.'
printf '%s\n' "$cmd" | grep -qE '(^|[;&|(`][[:space:]]*)(printenv|env)[[:space:]]*($|[;&|)`])' \
  && deny 'this prints the whole environment, which may hold secrets - print the variable you need by name.'
secret_shapes "$cmd" "The command"

# Fast path: nothing else to inspect.
case "$cmd" in *vela*|*git*) ;; *) exit 0 ;; esac

# `sh -c "..."` / `eval "..."`: the payload is quoted, so check the raw text conservatively.
if [ $approved = 0 ] \
   && printf '%s\n' "$cmd" | grep -Eq '(^|[[:space:];&|(])(eval|(ba|z|da|k)?sh[[:space:]]+(-[a-z]*[[:space:]]+)*-[a-z]*c)[[:space:]]' \
   && printf '%s\n' "$cmd" | grep -Eq 'vela[^;&|]*[[:space:]](apply|--auto-approve|--yes)([[:space:]"'"'"']|$)'; then
  deny_apply '"vela apply" inside sh -c / eval writes to a live org.'
fi

verdicts="$(printf '%s\n' "$cmd" | awk '
  # 1. Drop heredoc bodies (PR bodies, file contents).
  {
    if (delim != "") { t = $0; gsub(/^[ \t]+|[ \t]+$/, "", t); if (t == delim) delim = ""; next }
    line = $0
    if (match(line, /<<-?[ \t]*["\047]?[A-Za-z_][A-Za-z0-9_]*["\047]?/)) {
      d = substr(line, RSTART, RLENGTH); sub(/^<<-?[ \t]*/, "", d); gsub(/["\047]/, "", d); delim = d
    }
    text = text line "\n"
  }
  END {
    # 2. Replace quoted strings with a space (quotes are data, not commands).
    out = ""; n = length(text); q = ""
    for (i = 1; i <= n; i++) {
      c = substr(text, i, 1)
      if (q == "\047") { if (c == "\047") { q = ""; out = out " " } continue }
      if (q == "\"")   { if (c == "\\") { i++; continue } if (c == "\"") { q = ""; out = out " " } continue }
      if (c == "\\") { out = out substr(text, i, 2); i++; continue }
      if (c == "\047" || c == "\"") { q = c; continue }
      out = out c
    }
    # 3. Split into command segments; one verdict line per finding.
    gsub(/\$\(|[;&|()`\n]/, "\n", out)
    m = split(out, seg, "\n")
    for (s = 1; s <= m; s++) {
      k = split(seg[s], w, /[ \t]+/); j = 1
      while (j <= k && (w[j] == "" || w[j] ~ /^[A-Za-z_][A-Za-z0-9_]*=/ || w[j] ~ /^(env|command|exec|sudo|time|nohup|dotnet|tool|run)$/)) j++
      if (j > k) continue
      base = w[j]; sub(/.*\//, "", base)
      if (base == "vela" || base == "vela.exe") {
        help = 0; hit = ""
        for (x = j + 1; x <= k; x++) {
          if (w[x] == "--help" || w[x] == "-h") help = 1
          if (w[x] == "apply") hit = "apply"
          if (w[x] == "--auto-approve" || w[x] == "--yes") hit = "auto-approve"
        }
        if (hit != "" && !help) print hit
      }
      if (base == "git") {
        j++
        while (j <= k && (w[j] == "" || w[j] ~ /^-/)) { if (w[j] == "-C" || w[j] == "-c") j++; j++ }
        sc = w[j]; if (sc != "commit" && sc != "push") continue
        nv = 0; force = 0; prot = 0; pos = 0
        for (x = j + 1; x <= k; x++) {
          a = w[x]; if (a == "") continue
          if (a == "--no-verify") nv = 1
          else if (a ~ /^--force-with-lease/) continue
          else if (a == "--force" || a == "--mirror") { force = 1; if (a == "--mirror") prot = 1 }
          else if (a ~ /^-[A-Za-z]+$/) { if (sc == "commit" && a ~ /n/) nv = 1; if (sc == "push" && a ~ /f/) force = 1 }
          else if (a !~ /^-/) {
            pos++
            if (sc == "push" && pos >= 2) { if (a ~ /^\+/) force = 1; t = a; sub(/^\+/, "", t); if (t ~ /(^|:)(refs\/heads\/)?(main|master)$/) prot = 1 }
          }
        }
        if (nv) print "no-verify"
        if (sc == "push") { if (force) print "force"; if (prot) print "protected"; if (pos < 2) print "push-current" }
      }
    }
  }')"

for v in $verdicts; do
  case "$v" in
    apply)        [ $approved = 1 ] || deny_apply '"vela apply" writes to a live org.' ;;
    auto-approve) [ $approved = 1 ] || deny_apply '"--auto-approve"/"--yes" bypasses the confirmation of a write to a live org.' ;;
    no-verify)    deny '"--no-verify" (or "commit -n") skips the repository hooks - fix what they report instead.' ;;
    force)        deny 'a forced push rewrites published history - push a new commit, or use --force-with-lease on your own branch.' ;;
    protected)    deny 'pushing to main/master bypasses the pull request - push a branch and open a PR.' ;;
    push-current)
      b="$(git ${cwd:+-C "$cwd"} symbolic-ref --short -q HEAD 2>/dev/null)"
      case "$b" in main|master) deny "the current branch is $b: pushing it bypasses the pull request - push a branch and open a PR." ;; esac ;;
  esac
done
exit 0
